	"BridgeManagementV2/bmsadmin/view/BnacConfig.view.xml":'<mvc:View\n  controllerName="BridgeManagementV2.bmsadmin.controller.BnacConfig"\n  xmlns:mvc="sap.ui.core.mvc"\n  xmlns="sap.m"\n  xmlns:core="sap.ui.core"\n  xmlns:f="sap.ui.layout.form"\n  displayBlock="true"><Page id="bnacConfigPage" showHeader="true" class="sapUiContentPadding"><customHeader><Bar><contentLeft><Title text="BNAC Integration Configuration" level="H3" /></contentLeft><contentRight><Button icon="sap-icon://refresh" text="Refresh" press=".onRefreshEnvs" type="Transparent" /><Button icon="sap-icon://add" text="Add Environment" press=".onAddEnv" type="Emphasized" class="sapUiSmallMarginBegin" /><Button icon="sap-icon://information" tooltip="How to use this page" press=".onShowHelp" type="Transparent" class="sapUiSmallMarginBegin" /></contentRight></Bar></customHeader><content><VBox class="sapUiSmallMargin"><Title text="BNAC Environment URLs" level="H4" class="sapUiSmallMarginBottom" /><Table id="envTable" mode="None" noDataText="No environments configured."\n               items="{envModel>/environments}" class="sapUiSmallMarginBottom"><columns><Column width="120px"><Text text="Environment" /></Column><Column width="320px"><Text text="Base URL" /></Column><Column><Text text="Description" /></Column><Column width="80px"  hAlign="Center"><Text text="Active" /></Column><Column width="140px"><Text text="Modified By" /></Column><Column width="100px" hAlign="Center"><Text text="Actions" /></Column></columns><items><ColumnListItem><cells><Text text="{envModel>environment}" /><Link text="{envModel>baseUrl}" href="{envModel>baseUrl}" target="_blank" /><Text text="{envModel>description}" /><CheckBox selected="{envModel>active}" editable="false" /><Text text="{envModel>modifiedBy}" /><HBox justifyContent="Center"><Button icon="sap-icon://edit"   type="Transparent" press=".onEditEnv"   tooltip="Edit" /><Button icon="sap-icon://delete" type="Transparent" press=".onDeleteEnv" tooltip="Delete" /></HBox></cells></ColumnListItem></items></Table><Title text="BNAC Object ID Mass Load" level="H4" class="sapUiMediumMarginTop sapUiSmallMarginBottom" /><MessageStrip text="CSV format: bridgeId,bnacObjectId (one row per line, no header required)" type="Information" showCloseButton="false" class="sapUiSmallMarginBottom" /><HBox alignItems="Center" class="sapUiSmallMarginBottom"><Input id="fileNameDisplay" placeholder="No file selected" width="280px" editable="false" /><Button text="Browse..." press=".onBrowse" class="sapUiSmallMarginBegin" /><Select id="envSelect" width="120px" class="sapUiSmallMarginBegin"><items><core:Item key="DEV"     text="DEV" /><core:Item key="PREPROD" text="PREPROD" /><core:Item key="PROD"    text="PROD" /><core:Item key="TEST"    text="TEST" /></items></Select><Button id="uploadBtn" icon="sap-icon://upload" text="Upload BNAC IDs" press=".onUpload"\n                  type="Emphasized" class="sapUiSmallMarginBegin" enabled="false" /></HBox><MessageStrip id="uploadResult" visible="false" showCloseButton="true" class="sapUiSmallMarginBottom" /><Title text="Load History" level="H4" class="sapUiMediumMarginTop sapUiSmallMarginBottom" /><Table id="histTable" mode="None" noDataText="No BNAC load history."\n               items="{histModel>/history}"><columns><Column width="180px"><Text text="Loaded At" /></Column><Column width="160px"><Text text="Loaded By" /></Column><Column><Text text="File Name" /></Column><Column width="80px"  hAlign="Center"><Text text="Env" /></Column><Column width="80px"  hAlign="End"><Text text="Total" /></Column><Column width="80px"  hAlign="End"><Text text="Success" /></Column><Column width="80px"  hAlign="End"><Text text="Failed" /></Column></columns><items><ColumnListItem><cells><Text text="{histModel>loadedAtDisplay}" /><Text text="{histModel>loadedBy}" /><Text text="{histModel>fileName}" /><ObjectStatus text="{histModel>environment}" state="Information" /><ObjectNumber number="{histModel>total}"   emphasized="false" /><ObjectNumber number="{histModel>success}" state="Success" /><ObjectNumber number="{histModel>failed}"  state="{histModel>failedState}" /></cells></ColumnListItem></items></Table></VBox></content></Page><mvc:dependents><Dialog id="envDialog" contentWidth="440px"><content><f:SimpleForm layout="ColumnLayout" columnsM="1" editable="true" class="sapUiSmallMargin"><f:content><Label text="Environment Key" required="true"/><Input id="dlgEnvKey" value="{dlgEnv>/environment}" placeholder="e.g. STAGING"/><Label text="Base URL" required="true"/><Input id="dlgEnvUrl" value="{dlgEnv>/baseUrl}" placeholder="https://bnac-xxx.austroads.com.au/assets/"/><Label text="Description"/><Input id="dlgEnvDescr" value="{dlgEnv>/description}" placeholder="Optional description"/><Label text="Active"/><CheckBox id="dlgEnvActive" selected="{dlgEnv>/active}"/></f:content></f:SimpleForm></content><beginButton><Button text="Save" type="Emphasized" press=".onEnvDialogSave"/></beginButton><endButton><Button text="Cancel" press=".onEnvDialogClose"/></endButton></Dialog><Dialog id="infoDialog" contentWidth="480px"><content><ScrollContainer width="100%" vertical="true" height="60vh"><FormattedText id="infoDialogHtml" width="100%" class="sapUiSmallMargin"/></ScrollContainer></content><endButton><Button text="Close" press=".onInfoDialogClose"/></endButton></Dialog></mvc:dependents></mvc:View>\n',
